import json, re, random, sys, time
import chess

RULES = json.load(open('/tmp/obench-cell-7ir2q20u/bench_opencode_regex-chess_m4di54di/re.json'))


def run(fen):
    for p, r in RULES:
        fen = re.sub(p, r, fen)
    return [" ".join(x.split(" ")[:-2]) for x in fen.split("\n")]


def expected(board):
    out = set()
    for m in board.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        b = board.copy(); b.push(m)
        out.add(" ".join(b.fen().split(" ")[:-2]))
    return out


def check(fen):
    board = chess.Board(fen)
    exp = expected(board)
    ours = run(fen)
    if not exp:
        return True
    ok = len(ours) == len(exp) and all(x in exp or x.rpartition(" ")[0] + " -" in exp for x in ours)
    if not ok:
        print("FAIL", fen)
        print(" extra:", [x for x in ours if not (x in exp or x.rpartition(" ")[0] + " -" in exp)])
        print(" missing:", set(exp) - set(ours) - {x.rpartition(" ")[0] + " -" for x in ours})
    return ok


random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = 0; bad = 0; t0 = time.time()
for g in range(int(sys.argv[2]) if len(sys.argv) > 2 else 200):
    b = chess.Board()
    while not b.is_game_over() and b.ply() < 200:
        if b.turn == chess.WHITE:
            n += 1
            if not check(b.fen()):
                bad += 1
                if bad > 5: sys.exit(1)
        moves = list(b.legal_moves)
        # bias towards captures/pawn moves to reach interesting positions
        b.push(random.choice(moves))
print("tested", n, "bad", bad, "time", time.time() - t0)
